// IsRedstoneConductor 报告方块是否导强充能：显式覆盖优先，
// 否则使用“碰撞形状为整方块”的默认判定。
func IsRedstoneConductor(name string, fullCube bool) bool {
	if alwaysConductiveBlocks[name] {
		return true
	}
	if nonConductiveBlocks[name] {
		return false
	}
	return fullCube
}
